package com.primehr.rsp.evaluation.domain;

import com.primehr.rsp.domain.RspAuditedEntity;
import com.primehr.shared.exception.IllegalLifecycleTransitionException;
import jakarta.persistence.*;
import java.time.*;
import java.util.*;

@Entity @Table(name="rsp_evaluation_policy",uniqueConstraints=@UniqueConstraint(name="uk_rsp_evaluation_policy_version",columnNames={"agency_id","normalized_code","definition_version"}))
public class EvaluationPolicy extends RspAuditedEntity {
 public enum Status { DRAFT,PUBLISHED,SUPERSEDED } public enum Rounding { HALF_UP,HALF_EVEN,DOWN } public enum TieRule { COMPETITION,DENSE } public enum Aggregation { NORMALIZED_WEIGHTED_SUM }
 @Column(nullable=false,length=80) private String code; @Column(name="normalized_code",nullable=false,length=80) private String normalizedCode; @Column(nullable=false,length=200) private String name; @Column(length=2000) private String description; @Column(name="merit_selection_plan_reference",nullable=false,length=500) private String meritSelectionPlanReference; @Column(name="definition_version",nullable=false) private int definitionVersion; @Column(name="supersedes_id",length=36) private String supersedesId; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private Status status; @Column(name="effective_from") private LocalDate effectiveFrom; @Column(name="effective_to") private LocalDate effectiveTo; @Column(name="rounding_scale",nullable=false) private int roundingScale; @Enumerated(EnumType.STRING) @Column(name="rounding_mode",nullable=false,length=20) private Rounding roundingMode; @Enumerated(EnumType.STRING) @Column(name="tie_rule",nullable=false,length=30) private TieRule tieRule; @Enumerated(EnumType.STRING) @Column(name="aggregation_mode",nullable=false,length=40) private Aggregation aggregationMode; @Column(name="published_by",length=100) private String publishedBy; @Column(name="published_at") private Instant publishedAt;
 protected EvaluationPolicy(){}
 public EvaluationPolicy(String agency,String code,String name,String description,String msp,int version,String supersedesId,int scale,Rounding rounding,TieRule tie){super(agency);if(version<1)throw new IllegalArgumentException("definitionVersion must be positive");definitionVersion=version;this.supersedesId=optionalText(supersedesId);status=Status.DRAFT;apply(code,name,description,msp,scale,rounding,tie);}
 public void update(String code,String name,String description,String msp,int scale,Rounding rounding,TieRule tie){requireDraft();apply(code,name,description,msp,scale,rounding,tie);}
 public void publish(LocalDate from,LocalDate to,String actor,Instant at){requireDraft();if(from==null)throw new IllegalArgumentException("effectiveFrom is required");dates(from,to);effectiveFrom=from;effectiveTo=to;publishedBy=requiredText(actor,"actor");publishedAt=Objects.requireNonNull(at);status=Status.PUBLISHED;}
 public void supersede(LocalDate next){if(status!=Status.PUBLISHED)throw new IllegalLifecycleTransitionException("Only PUBLISHED policies may be superseded");if(next==null||!next.isAfter(effectiveFrom))throw new IllegalArgumentException("A successor must become effective after its predecessor");LocalDate end=next.minusDays(1);if(effectiveTo==null||effectiveTo.isAfter(end))effectiveTo=end;status=Status.SUPERSEDED;}
 public boolean effectiveOn(LocalDate date){return (status==Status.PUBLISHED||status==Status.SUPERSEDED)&&!date.isBefore(effectiveFrom)&&(effectiveTo==null||!date.isAfter(effectiveTo));}
 private void apply(String c,String n,String d,String m,int scale,Rounding rounding,TieRule tie){code=requiredText(c,"code");normalizedCode=code.toUpperCase(Locale.ROOT);name=requiredText(n,"name");description=optionalText(d);meritSelectionPlanReference=requiredText(m,"meritSelectionPlanReference");if(scale<0||scale>6)throw new IllegalArgumentException("roundingScale must be between 0 and 6");roundingScale=scale;roundingMode=Objects.requireNonNull(rounding);tieRule=Objects.requireNonNull(tie);aggregationMode=Aggregation.NORMALIZED_WEIGHTED_SUM;}
 private static void dates(LocalDate from,LocalDate to){if(from!=null&&to!=null&&to.isBefore(from))throw new IllegalArgumentException("effectiveTo cannot precede effectiveFrom");}
 private void requireDraft(){if(status!=Status.DRAFT)throw new IllegalLifecycleTransitionException("Published evaluation policies are immutable; create a successor");}
 public String getCode(){return code;} public String getNormalizedCode(){return normalizedCode;} public String getName(){return name;} public String getDescription(){return description;} public String getMeritSelectionPlanReference(){return meritSelectionPlanReference;} public int getDefinitionVersion(){return definitionVersion;} public String getSupersedesId(){return supersedesId;} public Status getStatus(){return status;} public LocalDate getEffectiveFrom(){return effectiveFrom;} public LocalDate getEffectiveTo(){return effectiveTo;} public int getRoundingScale(){return roundingScale;} public Rounding getRoundingMode(){return roundingMode;} public TieRule getTieRule(){return tieRule;} public Aggregation getAggregationMode(){return aggregationMode;} public String getPublishedBy(){return publishedBy;} public Instant getPublishedAt(){return publishedAt;}
}
